fn solve(input: Vec<char>) -> Vec<char> {
    // Get first two characters
    let first_char = input[0];
    let second_char = input[1];
    
    // Convert chars to digits
    let first_digit = first_char.to_digit(10).unwrap();
    let second_digit = second_char.to_digit(10).unwrap();
    
    // Define mapping from digit to good count
    let good_count = |d: u32| -> u32 {
        match d {
            0 => 2,
            1 => 7,
            2 => 2,
            3 => 3,
            4 => 3,
            5 => 4,
            6 => 2,
            7 => 5,
            8 => 1,
            9 => 2,
            _ => unreachable!(), // Input is guaranteed to be 0-9
        }
    };
    
    // Calculate product
    let product = good_count(first_digit) * good_count(second_digit);
    
    // Convert product to string and then to Vec<char>
    let mut result: Vec<char> = product.to_string().chars().collect();
    
    // Append newline character
    result.push('\n');
    
    result
}